float rand(vec2 co){
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    const float seed = 0.021f;
    const int nPts = 40;
    vec2 pts[nPts];
    for(int i = 0; i < nPts; ++i) {
        float xVal = mod(rand(vec2(float(i)*2.0f + seed, float(i)*4.0f + seed)), 0.8f) + 0.1f;
        float yVal = mod(rand(vec2(float(i)*6.0f + seed, float(i)*8.0f + seed)), 0.6f);
        pts[i] = vec2(xVal, yVal);
    }
    vec2 uv = fragCoord/iResolution.x;

    const float linewidth = 0.01;
    float radius = mod(0.04f * iTime, 0.2f);

    int closestPtIdx = -1, closestPtIdx2 = -1;
    float closestPtDist = 1000.0f, closestPtDist2 = 1000.0f;

    for(int i = 0; i < nPts; ++i) {
        if(length(uv - pts[i]) < closestPtDist) {
            if(closestPtDist < closestPtDist2) {
                closestPtIdx2 = closestPtIdx;
                closestPtDist2 = closestPtDist;
            }
            closestPtDist = length(uv - pts[i]);
            closestPtIdx = i;
        } else if(length(uv - pts[i]) < closestPtDist2) {
            closestPtIdx2 = i;
            closestPtDist2 = length(uv - pts[i]);
        }
    }

    vec3 col = vec3(1,1,1);
    if(closestPtDist < radius)
        col = vec3(mod(rand(vec2(closestPtIdx*1, 0)),0.2f),0.7 + mod(rand(vec2(closestPtIdx*1, 0)), 0.3f),1);

    if(closestPtDist < linewidth) {
        //col = vec3(0,0,0);
    }

    vec2 disp12 = normalize(pts[closestPtIdx] - pts[closestPtIdx2]);
    float dist1 = abs(dot(disp12, uv - pts[closestPtIdx])); 
    float dist2 = abs(dot(disp12, uv - pts[closestPtIdx2])); 

    if(closestPtDist < (radius) && (abs(dist1 - dist2) < (linewidth))) {
        col = vec3(0,0,0);
    }
    else if(closestPtDist > radius - linewidth*0.5 && closestPtDist < radius + linewidth*0.5) {
        col = vec3(0,0,0);
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}
